(()=>{'use strict';const entries=[];for(const card of document.querySelectorAll('article')){const video=card.querySelector('video'),input=card.querySelector('input'),status=card.querySelector('.status');const entry={video,url:null};entries.push(entry);input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;video.pause();video.removeAttribute('src');video.load();if(entry.url)URL.revokeObjectURL(entry.url);entry.url=URL.createObjectURL(file);video.src=entry.url;video.muted=true;video.loop=true;status.textContent='Video yükleniyor…';try{await video.play();status.textContent='Video oynuyor. Hareket sonunda yeniden başlar.';}catch{status.textContent='Oynat düğmesine bas. Video açılmıyorsa MP4 biçimini kullan.';}});video.addEventListener('error',()=>{status.textContent='Bu video açılamadı. MP4 biçiminde başka bir dosya seç.';});}document.addEventListener('visibilitychange',()=>{if(document.hidden)entries.forEach(e=>e.video.pause());});window.addEventListener('pagehide',()=>entries.forEach(e=>{e.video.pause();if(e.url)URL.revokeObjectURL(e.url);}));})();
